body.raw:
{
  "model": "{{model}}",
  "messages": [
    {
      "role": "system",
      "content": "Answer in exactly one word."
    },
    {
      "role": "user",
      "content": "Capital of France?"
    }
  ]
}

{
  "model": "{{model}}",
  "messages": [
    {
      "role": "user",
      "content": "What is ML?"
    },
    {
      "role": "assistant",
      "content": "Machine learning is a subset of AI."
    },
    {
      "role": "user",
      "content": "Give one example, briefly."
    }
  ]
}

{
  "model": "{{model}}",
  "messages": [
    {
      "role": "user",
      "content": "What's the weather in Paris?"
    },
    {
      "role": "assistant",
      "content": null,
      "tool_calls": [
        {
          "id": "call_1",
          "type": "function",
          "function": {
            "name": "get_weather",
            "arguments": "{\"city\":\"Paris\"}"
          }
        }
      ]
    },
    {
      "role": "tool",
      "tool_call_id": "call_1",
      "name": "get_weather",
      "content": "{\"temp_c\": 18}"
    },
    {
      "role": "user",
      "content": "Summarise that in one line."
    }
  ]
}

{
  "model": "{{model}}",
  "stream": true,
  "messages": [
    {
      "role": "user",
      "content": "List three primary colors, one per line."
    }
  ]
}

{
  "model": "{{model}}",
  "stream": true,
  "stream_options": {
    "include_usage": true
  },
  "messages": [
    {
      "role": "user",
      "content": "Name two colors, comma separated."
    }
  ]
}

{
  "model": "{{model}}",
  "reasoning_effort": "high",
  "messages": [
    {
      "role": "user",
      "content": "If a train covers 60km in 45 minutes, what is its speed in km/h?"
    }
  ]
}

{
  "model": "{{model}}",
  "response_format": {
    "type": "json_object"
  },
  "messages": [
    {
      "role": "user",
      "content": "Give me an object with keys name and city."
    }
  ]
}

{
  "model": "{{model}}",
  "prompt": "Write one short sentence about the sea."
}
